import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

const LIBRARY_DOCS_INVOKED = "Sub-agent library_docs invoked";
const LIBRARY_DOCS_STOPPED = "Sub-agent library_docs stopped";
const INSPECTOR_TOOLBOX_INVOKED = "Sub-agent inspector_toolbox invoked";
const INSPECTOR_TOOLBOX_STOPPED = "Sub-agent inspector_toolbox stopped";
const CUSTOM_TOOL_USED = "Tool inspector_success_marker used";

export const triggerAgentSuccessAndAssertEvents = async (page: Page) => {
  await test.step("Send inspector agent success trigger", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("inspector test agent success");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
  });

  await test.step("Provide library_docs collect follow-ups", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("next.js");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
    const midCount = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("How do I use middleware?");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(midCount + 1);
    const afterQuestionCount = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("Thanks, that's all I need.");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(afterQuestionCount + 1);
  });

  await test.step("Assert sub-agent invoked and stopped events in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(LIBRARY_DOCS_INVOKED);
    await ui.conversationLog.assertions(page).conversationEventReached(LIBRARY_DOCS_STOPPED);
  });
};

export const triggerCustomToolSuccessAndAssertEvents = async (page: Page) => {
  await test.step("Send inspector custom tool success trigger", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage("inspector test custom tool success");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
  });

  await test.step("Assert inspector_toolbox sub-agent and tool events in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(INSPECTOR_TOOLBOX_INVOKED);
    await ui.conversationLog.assertions(page).conversationEventReached(INSPECTOR_TOOLBOX_STOPPED);
    await ui.conversationLog.assertions(page).conversationEventReached(CUSTOM_TOOL_USED);
  });
};

export const openSubAgentEventDetailsAndAssert = async (page: Page) => {
  await test.step("Click sub-agent invoked event", async () => {
    await ui.conversationLog.actions(page).clickConversationEvent(LIBRARY_DOCS_INVOKED);
  });

  await test.step("Assert sub-agent event details panel", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("Sub-agent event details");
    await ui.eventDetails.assertions(page).panelContainsText("library_docs");
    await ui.eventDetails.assertions(page).panelContainsText("Description");
    await ui.eventDetails.assertions(page).panelContainsText("Tools");
  });
};
